insert into public.questions (subject_id, source_ref, prompt, options, correct_index, explanation, difficulty, topic, question_type, status, sort_order, banca, concurso)
values
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-126', 'A organizacao da administracao publica brasileira, nos termos constitucionais, compreende, entre outros, os principios da:', '["Legalidade, impessoalidade, moralidade, publicidade e eficiencia (LIMPE).","Autonomia, independencia e inamovibilidade.","Isonomia, contraditorio e ampla defesa.","Soberania, cidadania e dignidade.","Presuncao de inocencia e devido processo."]'::jsonb, 0, 'O art. 37 da Constituicao vincula a administracao publica aos principios da legalidade, impessoalidade, moralidade, publicidade e eficiencia.', 'easy', 'Organizacao da Administracao Publica', 'multiple_choice', 'published', 5195, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-127', 'Os vicios do ato administrativo podem ser classificados como:', '["Apenas vicio de forma.","Vicios de competencia, forma, motivo, objeto e finalidade.","Somente vicio de motivo.","Vicio de jurisprudencia e de costume.","Vicio de publicidade e de sigilo."]'::jsonb, 1, 'A doutrina classifica os vicios do ato administrativo em competencia, forma, motivo, objeto e finalidade.', 'medium', 'Atos administrativos', 'multiple_choice', 'published', 5196, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-128', 'Os poderes administrativos incluem, entre outros, o poder:', '["Judiciario, privativo dos tribunais.","Legislativo, exercido pelo Congresso.","Hierarquico, disciplinar, regulamentar e de policia.","Constituinte, reservado a Assembleia Nacional.","Executivo, privativo do Presidente."]'::jsonb, 2, 'A administracao dispoe de poderes hierarquico, disciplinar, regulamentar e de policia, entre outros, nos limites legais.', 'medium', 'Principios e poderes da Administracao', 'multiple_choice', 'published', 5197, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-129', 'Um tema misto em direito administrativo pode envolver, por exemplo:', '["Apenas questoes de direito penal.","A interseccao entre administracao publica e outros ramos do direito, como responsabilidade civil do Estado.","Somente questoes tributarias.","Apenas direito internacional.","Questoes de direito empresarial exclusivamente."]'::jsonb, 1, 'Temas mistos envolvem a interface do direito administrativo com outros ramos, como responsabilidade civil, constitucional e processual.', 'medium', 'Temas mistos', 'multiple_choice', 'published', 5198, 'VUNESP', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-130', 'O principio do desenvolvimento sustentavel, no direito ambiental, busca:', '["O crescimento economico a qualquer custo.","O equilibrio entre desenvolvimento economico e protecao ambiental para as presentes e futuras geracoes.","A proibicao de toda atividade economica.","A exploracao irrestrita dos recursos naturais.","A transferencia de poluicao para outros paises."]'::jsonb, 1, 'O desenvolvimento sustentavel concilia crescimento economico com preservacao ambiental, atendendo as necessidades presentes e futuras.', 'medium', 'Teoria geral e principios de Direito Ambiental', 'multiple_choice', 'published', 5199, 'CEBRASPE', 'Area fiscal'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-131', 'A Constituicao reconhece o meio ambiente ecologicamente equilibrado como:', '["Bem de uso comum do povo e essencial a sadia qualidade de vida.","Propriedade privada do Estado.","Recurso economico livre.","Bem de uso especial do governo.","Mercadoria livremente negociavel."]'::jsonb, 0, 'O art. 225 da Constituicao reconhece o meio ambiente ecologicamente equilibrado como bem de uso comum do povo e essencial a sadia qualidade de vida.', 'easy', 'Direito Constitucional Ambiental', 'multiple_choice', 'published', 5200, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-132', 'A Lei de Politica Nacional do Meio Ambiente (Lei n. 6.938/81) institui, entre outros instrumentos, a:', '["Licenca ambiental, o EIA/RIMA e o SISNAMA.","Imunidade tributaria ambiental.","Desapropriacao de todas as areas verdes.","Privatizacao de parques nacionais.","Dispensa de licenciamento para mineracao."]'::jsonb, 0, 'A PNMA institui o SISNAMA, o licenciamento ambiental e o EIA/RIMA, entre outros instrumentos de gestao.', 'medium', 'Lei de Politica Nacional do Meio Ambiente (Lei n. 6.938/81) e LC n. 140/2011', 'multiple_choice', 'published', 5201, 'VUNESP', 'Area fiscal'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-133', 'A responsabilidade civil por dano ambiental, em regra:', '["Exige prova de dolo do poluidor.","E objetiva, sem prejuizo do nexo causal e do dano.","Depende de condenacao criminal.","E inexistente se houver licenca ambiental.","E subsidiaria do Estado."]'::jsonb, 1, 'A responsabilidade civil ambiental e objetiva, mas ainda exige a identificacao do dano e do nexo causal.', 'medium', 'Responsabilidade civil e administrativa no dano ambiental e tutela processual', 'multiple_choice', 'published', 5202, 'FGV', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-134', 'O Estatuto da Cidade (Lei n. 10.257/2001) estabelece, entre outros instrumentos, o:', '["Plano diretor, a funcao social da propriedade e o parcelamento do solo.","Desapropriacao sumaria de imoveis.","Imunidade tributaria urbana.","Privatizacao de vias publicas.","Dispensa de licenciamento para construcao."]'::jsonb, 0, 'O Estatuto da Cidade institui o plano diretor, a funcao social da propriedade urbana e regras de parcelamento do solo.', 'medium', 'Estatuto da Cidade (Lei n. 10.257/2001)', 'multiple_choice', 'published', 5203, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-135', 'A teoria geral do meio ambiente, segundo a doutrina, considera o meio ambiente como:', '["Apenas o meio natural.","O conjunto de condicoes, leis, influencias e interacoes que permitem a existencia da vida.","Somente as areas de preservacao permanente.","Apenas os recursos naturais economicamente exploraveis.","O ambiente urbano exclusivamente."]'::jsonb, 1, 'A teoria geral considera o meio ambiente como o conjunto de condicoes e interacoes que permitem a vida e o desenvolvimento.', 'medium', 'Teoria geral do Meio Ambiente', 'multiple_choice', 'published', 5204, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-136', 'O direito ambiental administrativo envolve, entre outros, o:', '["Licenciamento, fiscalizacao e sancoes administrativas ambientais.","Julgamento criminal exclusivo.","Desapropriacao de todas as propriedades rurais.","Imunidade civil do poluidor.","Privatizacao de unidades de conservacao."]'::jsonb, 0, 'O direito ambiental administrativo compreende licenciamento, fiscalizacao e sancoes administrativas, entre outros instrumentos.', 'medium', 'Direito Ambiental Administrativo', 'multiple_choice', 'published', 5205, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-137', 'A Lei de Introducao as Normas do Direito Brasileiro (LINDB) orienta a aplicacao da lei no tempo e no espaco. A lei nova, em regra:', '["Retroage sempre, mesmo em prejuizo.","Nao retroage, salvo disposicao em contrario ou quando for de ordem publica e interesse social.","Retroage apenas em favor do Estado.","Aplica-se apenas a contratos anteriores.","Substitui automaticamente toda lei anterior."]'::jsonb, 1, 'A LINDB estabelece que a lei nao retroage, salvo disposicao em contrario ou quando for de ordem publica e interesse social.', 'medium', 'Lei de Introducao as Normas do Direito Brasileiro - LINDB, Hierarquia e Interpretacao de Leis', 'multiple_choice', 'published', 5206, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-138', 'As pessoas naturais adquirem personalidade civil:', '["A partir da concepcao, para todos os efeitos.","Com o nascimento com vida, conforme o Codigo Civil.","A partir da maioridade.","Apenas com a obtencao de CPF.","Com o casamento."]'::jsonb, 1, 'A personalidade civil da pessoa natural comeca com o nascimento com vida, conforme o Codigo Civil.', 'easy', 'Pessoas Naturais', 'multiple_choice', 'published', 5207, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-139', 'As pessoas juridicas de direito privado adquirem personalidade juridica:', '["Com a assinatura do contrato social, automaticamente.","Com o registro no orgao competente, conforme a lei.","Com a primeira venda realizada.","Com a obtencao de CNPJ, apenas.","Com a autorizacao judicial."]'::jsonb, 1, 'A pessoa juridica de direito privado adquire personalidade juridica com o registro dos atos constitutivos no orgao competente.', 'medium', 'Pessoas Juridicas', 'multiple_choice', 'published', 5208, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-140', 'Os bens podem ser classificados, entre outras formas, em:', '["Apenas moveis e imoveis.","Moveis e imoveis, fungiveis e infungiveis, consumiveis e inconsumiveis, divisíveis e indivisiveis, singulares e coletivos.","Somente publicos e privados.","Apenas corporeos e incorporais.","Somente litigiosos e iliquidos."]'::jsonb, 1, 'O Codigo Civil classifica os bens em moveis e imoveis, fungiveis e infungiveis, consumiveis e inconsumiveis, divisíveis e indivisiveis, singulares e coletivos.', 'medium', 'Bens', 'multiple_choice', 'published', 5209, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-141', 'A teoria geral dos fatos juridicos distingue os fatos de:', '["Apenas atos juridicos e negocios juridicos.","Fato juridico (natural) e ato juridico (humano), com subcategorias.","Somente contratos e delitos.","Apenas atos lícitos e ilícitos.","Fatos materiais e fatos processuais."]'::jsonb, 1, 'A teoria geral dos fatos juridicos distingue fatos juridicos (naturais) e atos juridicos (humanos), com suas subcategorias.', 'medium', 'Teoria Geral dos Fatos Juridicos', 'multiple_choice', 'published', 5210, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-142', 'O adimplemento da obrigacao, em regra, ocorre com o pagamento:', '["Em qualquer lugar, sem necessidade de prova.","Do objeto da obrigacao ao credor, no tempo, lugar e forma previstos.","Apenas em dinheiro, mesmo que a obrigacao seja de fazer.","Somente mediante sentenca judicial.","Apenas por compensacao."]'::jsonb, 1, 'O adimplemento ocorre com a prestacao do objeto da obrigacao ao credor, conforme o tempo, lugar e forma previstos.', 'medium', 'Adimplemento e Extincao das Obrigacoes: Pagamento', 'multiple_choice', 'published', 5211, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-143', 'A transmissao das obrigacoes, em regra:', '["Ocorre automaticamente em qualquer caso.","Depende de cessao de credito ou assuncao de divida, observadas as formalidades legais.","E proibida pelo Codigo Civil.","Exige autorizacao judicial sempre.","Ocorre apenas por heranca."]'::jsonb, 1, 'A transmissao de obrigacoes ocorre por cessao de credito ou assuncao de divida, com as formalidades legais aplicaveis.', 'medium', 'Transmissao das Obrigacoes', 'multiple_choice', 'published', 5212, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-144', 'O inadimplemento da obrigacao pode gerar, em regra:', '["Apenas a extincao da obrigacao.","A responsabilidade civil do devedor, com perdas e danos, e, conforme o caso, a resolucao do contrato.","A prisao civil do devedor em qualquer hipotese.","A nulidade do contrato.","A transferencia do credito ao devedor."]'::jsonb, 1, 'O inadimplemento pode gerar responsabilidade civil do devedor e, conforme o caso, a resolucao do contrato.', 'medium', 'Inadimplemento das Obrigacoes', 'multiple_choice', 'published', 5213, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-145', 'A extincao do contrato pode ocorrer por:', '["Apenas por acordo entre as partes.","Cumprimento, rescisao, resolucao, resiliacao, novacao, confusao, compensacao ou prescricao, entre outros.","Somente por sentenca judicial.","Apenas por impossibilidade de execucao.","Somente por morte das partes."]'::jsonb, 1, 'O contrato se extingue por cumprimento, rescisao, resolucao, resiliacao, novacao, confusao, compensacao ou prescricao, entre outros modos.', 'medium', 'Extincao do Contrato', 'multiple_choice', 'published', 5214, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-146', 'Os contratos em especie incluem, entre outros:', '["Apenas o contrato de compra e venda.","Compra e venda, locacao, emprestimo, mandato, fianca, deposito, seguro, entre outros.","Somente contratos empresariais.","Apenas contratos administrativos.","Somente contratos de trabalho."]'::jsonb, 1, 'O Codigo Civil regula diversos contratos em especie, como compra e venda, locacao, emprestimo, mandato, fianca, deposito e seguro.', 'medium', 'Contratos em Especie e Atos Unilaterais', 'multiple_choice', 'published', 5215, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-147', 'A propriedade, no Codigo Civil, pode ser:', '["Apenas individual e absoluta.","Individual ou comum, com direito de usar, gozar e dispor do bem.","Somente coletiva.","Apenas temporaria.","Somente de bens moveis."]'::jsonb, 1, 'A propriedade e o direito de usar, gozar e dispor do bem, podendo ser individual ou comum.', 'medium', 'Propriedade', 'multiple_choice', 'published', 5216, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-148', 'Os direitos de vizinhanca impoem ao proprietario o dever de:', '["Usar o imovel sem qualquer limitacao.","Abster-se de atos que causem incomodo excessivo ou risco aos vizinhos, conforme a lei.","Construir livremente, sem observar recuos.","Transferir a propriedade ao vizinho.","Pagar indenizacao automatica."]'::jsonb, 1, 'Os direitos de vizinhanca impoem limites ao uso da propriedade para evitar incomodo excessivo ou risco aos vizinhos.', 'medium', 'Direitos de Vizinhanca', 'multiple_choice', 'published', 5217, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-149', 'Os direitos reais em coisa alheia incluem, entre outros:', '["Apenas a propriedade.","Usufruto, uso, habitacao, servidao e enfiteuse.","Somente a hipoteca.","Apenas o penhor.","Somente a anticrese."]'::jsonb, 1, 'Os direitos reais em coisa alheia incluem usufruto, uso, habitacao, servidao e enfiteuse.', 'medium', 'Direitos Reais em Coisa Alheia', 'multiple_choice', 'published', 5218, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-150', 'O casamento, no Codigo Civil, e:', '["Um contrato comercial.","Um contrato solene, com requisitos formais, que gera efeitos pessoais e patrimoniais.","Um ato administrativo.","Uma uniao de fato, sem formalidades.","Um contrato de trabalho."]'::jsonb, 1, 'O casamento e contrato solene, com requisitos formais, que gera efeitos pessoais e patrimoniais.', 'easy', 'Direito Pessoal de Familia: Casamento', 'multiple_choice', 'published', 5219, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-151', 'A filiacao pode ser estabelecida por:', '["Apenas por vinculo biologico.","Vinculo biologico ou socioafetivo, conforme a lei e a jurisprudencia.","Apenas por adocao.","Somente por reconhecimento judicial.","Apenas por casamento."]'::jsonb, 1, 'A filiacao pode ser estabelecida por vinculo biologico ou socioafetivo, conforme a lei e a jurisprudencia.', 'medium', 'Filiacao, Reconhecimento dos Filhos, Adocao e Guarda', 'multiple_choice', 'published', 5220, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-152', 'O poder familiar compreende, entre outros, o direito e o dever de:', '["Abandonar os filhos, em qualquer caso.","Guardar, criar, educar e representar os filhos menores.","Dispor dos bens dos filhos livremente.","Impedir o acesso a educacao.","Transferir a tutela a terceiros."]'::jsonb, 1, 'O poder familiar compreende o direito e o dever de guardar, criar, educar e representar os filhos menores.', 'medium', 'Poder Familiar', 'multiple_choice', 'published', 5221, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-153', 'A uniao estavel, para ser reconhecida, exige, em regra:', '["Apenas a convivencia, sem outros requisitos.","Convivencia publica, continua e duradoura, com o objetivo de constituir familia.","Apenas o registro em cartorio.","A autorizacao judicial previa.","A existencia de filhos."]'::jsonb, 1, 'A uniao estavel exige convivencia publica, continua e duradoura, com o objetivo de constituir familia.', 'medium', 'Uniao Estavel e Concubinato', 'multiple_choice', 'published', 5222, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-154', 'A sucessao em geral ocorre:', '["Apenas por testamento.","Por lei ou por testamento, conforme o caso.","Somente por heranca legítima.","Apenas por doacao.","Somente por contrato."]'::jsonb, 1, 'A sucessao ocorre por lei (legítima) ou por testamento (testamentaria), conforme o caso.', 'medium', 'Sucessoes em Geral', 'multiple_choice', 'published', 5223, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-155', 'A sucessao legitima segue a ordem de vocacao hereditaria definida pela lei, que privilegia, em regra:', '["Os amigos do falecido.","Os herdeiros necessarios, conforme as classes legais.","O Estado, em qualquer caso.","Os credores.","O municipio."]'::jsonb, 1, 'A sucessao legitima segue a ordem legal de vocacao hereditaria, privilegiando os herdeiros necessarios.', 'medium', 'Sucessao Legitima', 'multiple_choice', 'published', 5224, 'VUNESP', 'Tribunais')
